/* BoxBox Academy – interfejs okna (osadzony w Qt WebEngine).
   Układ i style z makiety; dane przychodzą z Pythona przez QWebChannel (obiekt `bridge`).
   Zasada: ten plik tylko rysuje i wysyła akcje; nic nie liczy. */
(() => {
'use strict';
let bridge = null;
let D = null;                 // pełne dane z Pythona (patrz boxbox/gui/data.py)
const ui = { view: 'start', settingsTab: 'sound', helpTab: 'glossary', overlayVisible: false, toast: '', wizardStep: 0,
             corner: '', lesson: '', sessionName: 'sesja', record: true, overlay: true, quiet: false, photoPicker: false, photos: [] };
const NAV = [['start','Start','home'],['analysis','Analiza','chart'],['progress','Postęp','trend'],['lessons','Lekcje','book'],['driver','Karta kierowcy','id'],['settings','Ustawienia','settings']];
const H = {start:['Start','Trener na radiu. Twój kolejny krok do szybszej i pewniejszej jazdy.'],analysis:['Analiza','Zobacz, gdzie zyskujesz czas i co poprawić na kolejnym okrążeniu.'],progress:['Postęp','Twoja droga od pierwszego okrążenia do jazdy bez asyst.'],lessons:['Lekcje','Jedna umiejętność na raz. Małe kroki, realny postęp.'],driver:['Karta kierowcy','Twoja licencja, statystyki i zdobyte doświadczenie.'],settings:['Ustawienia','Dostosuj swojego trenera, nakładkę i sposób zapisywania sesji.'],help:['Pomoc','Słownik pojęć, samouczek i zgłoszenie problemu.'],wizard:['Pierwsze uruchomienie','Cztery krótkie kroki i jesteś gotowy na pierwszy trening.'],summary:['Podsumowanie sesji','Każda sesja to konkretna informacja, co zrobiłeś dobrze i co dalej.']};

const defs=`<svg width="0" height="0" style="position:absolute;overflow:hidden" aria-hidden="true" xmlns="http://www.w3.org/2000/svg"><defs>
<symbol id="i-home" viewBox="0 0 24 24"><path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/></symbol>
<symbol id="i-chart" viewBox="0 0 24 24"><path d="M3 3v18h18"/><path d="m6 15 4-5 4 3 5-7"/></symbol>
<symbol id="i-trend" viewBox="0 0 24 24"><path d="m3 18 7-7 4 4 7-9"/><path d="M16 6h5v5"/></symbol>
<symbol id="i-book" viewBox="0 0 24 24"><path d="M12 6c-3-2-6-2-9-1v14c3-1 6-1 9 1 3-2 6-2 9-1V5c-3-1-6-1-9 1z"/><path d="M12 6v14"/></symbol>
<symbol id="i-id" viewBox="0 0 24 24"><rect x="2" y="4" width="20" height="16" rx="3"/><circle cx="8" cy="10" r="2"/><path d="M4.5 16c.5-3 6.5-3 7 0M14 9h5m-5 4h5"/></symbol>
<symbol id="i-settings" viewBox="0 0 24 24"><path d="M10 2h4l.7 2.6 2 .9 2.4-1.1 2.7 3-.9 2.3.8 2.1 2.3.8v3.7l-2.3.8-.8 2.1.9 2.3-2.7 3-2.4-1.1-2 .9L14 24h-4l-.7-2.7-2-.9-2.4 1.1-2.7-3 .9-2.3-.8-2.1L0 13.3V9.6l2.3-.8.8-2.1-.9-2.3 2.7-3 2.4 1.1 2-.9z" transform="translate(1 -1) scale(.92)"/><circle cx="12" cy="12" r="3"/></symbol>
<symbol id="i-help" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><path d="M9 9a3 3 0 1 1 4 2.9c-1 .5-1 1-1 2.1"/><path d="M12 17h.01"/></symbol>
<symbol id="i-play" viewBox="0 0 24 24"><path d="m8 5 11 7-11 7z"/></symbol>
<symbol id="i-stop" viewBox="0 0 24 24"><rect x="5" y="5" width="14" height="14" rx="2"/></symbol>
<symbol id="i-arrow" viewBox="0 0 24 24"><path d="M4 12h16m-7-7 7 7-7 7"/></symbol>
<symbol id="i-user" viewBox="0 0 24 24"><circle cx="12" cy="8" r="4"/><path d="M4 22a8 8 0 0 1 16 0"/></symbol>
<symbol id="i-volume" viewBox="0 0 24 24"><path d="M4 9h4l5-4v14l-5-4H4zM17 8a6 6 0 0 1 0 8M19 5a10 10 0 0 1 0 14"/></symbol>
<symbol id="i-headphones" viewBox="0 0 24 24"><path d="M3 14v-3a9 9 0 0 1 18 0v3M3 13h5v8H5a2 2 0 0 1-2-2zm13 0h5v6a2 2 0 0 1-2 2h-3z"/></symbol>
<symbol id="i-flag" viewBox="0 0 24 24"><path d="M5 21V3m0 1c6-3 8 3 15 0v11c-7 3-9-3-15 0"/></symbol>
<symbol id="i-target" viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/></symbol>
<symbol id="i-clock" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><path d="M12 5v7l4 3"/></symbol>
<symbol id="i-download" viewBox="0 0 24 24"><path d="M12 3v13m-5-5 5 5 5-5M3 20h18"/></symbol>
<symbol id="i-bolt" viewBox="0 0 24 24"><path d="m13 2-9 12h7l-1 8 10-13h-7z"/></symbol>
<symbol id="i-check" viewBox="0 0 24 24"><path d="m4 12 5 5L20 6"/></symbol>
<symbol id="i-shield" viewBox="0 0 24 24"><path d="m12 2 9 4v6c0 6-5 9-9 10-4-1-9-4-9-10V6z"/><path d="m8 12 3 3 5-6"/></symbol>
<symbol id="i-wrench" viewBox="0 0 24 24"><path d="M14 6a6 6 0 0 1 7-3l-4 4 1 3 3 1 3-3a6 6 0 0 1-7 8L8 23a3 3 0 0 1-4-4z" transform="translate(-2 0) scale(.95)"/></symbol>
<symbol id="i-spark" viewBox="0 0 24 24"><path d="m12 1 2.5 8.5L23 12l-8.5 2.5L12 23l-2.5-8.5L1 12l8.5-2.5z"/></symbol>
<symbol id="i-layers" viewBox="0 0 24 24"><path d="m12 3 10 6-10 6L2 9zm-10 11 10 6 10-6"/></symbol>
</defs></svg>`;
const ico=(key)=>`<svg class="svg-icon" aria-hidden="true"><use href="#i-${key}"></use></svg>`;
const esc=(s)=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(label,action,cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const switcher=(name,label,description='')=>`<div class="switch-row"><div><div class="switch-title">${label}</div>${description?`<div class="switch-sub">${description}</div>`:''}</div><button type="button" role="switch" aria-checked="${!!val(name)}" aria-label="${label}" class="switch ${val(name)?'on':''}" data-toggle="${name}"></button></div>`;
const tagline=(t)=>`<span class="tag">${t}</span>`;
const progress=(percent)=>`<div class="progress"><span style="width:${Math.max(0,Math.min(100,percent))}%"></span></div>`;
const head=(title,sub='',extra='')=>`<div class="panel-header"><div><h2 class="section-title">${title}</h2>${sub?`<p class="section-sub">${sub}</p>`:''}</div>${extra}</div>`;
const metric=(value,label,col='')=>`<div class="metric"><div class="num ${col}">${value}</div><div class="caption">${label}</div></div>`;
const sec=(s)=>{s=Math.max(0,Math.floor(s||0));const h=Math.floor(s/3600),m=Math.floor(s%3600/60),x=s%60;return (h?String(h).padStart(2,'0')+':':'')+String(m).padStart(2,'0')+':'+String(x).padStart(2,'0')};
const deltaCls=(d)=>d==null?'':(d<0?'green':d>0?'amber':'');
const fmtDelta=(d)=>d==null?'–':(d>0?'+':'−')+Math.abs(d).toFixed(2).replace('.',',')+' s';
function brandIcon(size=46){return `<svg viewBox="0 0 76 64" width="${size}" height="${size}" aria-hidden="true"><path d="M4 12v13m8-22v29m8-17v9m8-19v27m8-22v12m8-19v27m8-15v14m8-22v19m8-14v11" stroke="#19e6e6" stroke-width="3" stroke-linecap="round" opacity=".95"/><path d="M15 37 5 43l1 10h12l8-4h24l8 4h12l1-10-10-6-8-3-8-8H31l-8 8z" fill="#f1f5fb"/><path d="M16 38h44M28 32h21M9 51h60" stroke="#ff3c42" stroke-width="3.5"/><path d="M29 38h18l4 10H25z" fill="#131c2b"/><path d="M38 28v17" stroke="#a9bacb" stroke-width="3"/></svg>`}

// wartości przełączników: część w ustawieniach (Python), część lokalnie w oknie
function val(name){ if(['record','overlay','quiet'].includes(name)) return ui[name]; return D.settings[name]; }

const topStatus=()=>{const s=D.status; let txt, cls='';
  if(s.busy){txt=`Port ${s.port} zajęty · zamknij inny program z telemetrią`;cls='off'}
  else if(s.connected){txt=`Gra połączona · ${esc(s.track||'tor nieznany')} · ${s.rate} pakietów/s`}
  else {txt=`Czekam na grę · port ${s.port}`;cls='off'}
  return `<span class="status ${cls}"><i class="dot"></i>${txt}</span>`};

function side(){return `<aside class="side"><div class="brand"><span class="brand-mark">${brandIcon()}</span><span class="brand-txt"><strong>BoxBox</strong><span>ACADEMY</span></span></div><div class="side-overline">NAWIGACJA</div><nav class="nav" aria-label="Nawigacja główna">${NAV.map(([id,label,icon])=>`<button class="nav-item ${ui.view===id?'active':''}" data-nav="${id}" title="${label}">${ico(icon)}<span class="nav-label">${label}</span></button>`).join('')}</nav><div class="side-spacer"></div><div class="side-bottom"><button class="nav-item ${ui.view==='help'?'active':''}" data-nav="help">${ico('help')}<span class="nav-label">Pomoc i wsparcie</span></button><div class="side-card"><div class="side-card-row"><i class="dot" style="${D.status.connected?'':'background:#5b6676;box-shadow:none'}"></i><strong>${D.live?'Sesja na żywo':'System treningowy'}</strong></div><div class="small-txt mt-10">${esc(D.app.game)} · ${D.live?'trener aktywny':(D.status.connected?'gra połączona':'czekam na grę')}</div></div><div class="side-footer"><span>BETA ${esc(D.app.version)}</span><span>${esc(D.app.build)}</span></div></div></aside>`}
function shell(){let [title,description]=H[ui.view]||H.start; return `${defs}<div class="app-layout">${side()}<main class="main"><header class="header"><div><div class="eyebrow">BOXBOX ACADEMY <span style="color:#46566a;margin:0 7px">/</span> ${esc(D.app.game).toUpperCase()}</div><h1 class="page-title">${title}</h1><p class="page-sub">${description}</p></div><div class="header-right">${topStatus()}</div></header>${renderView()}<footer class="footer-note"><span><strong>BoxBox Academy</strong> · trener jazdy · wszystkie dane zostają na tym komputerze</span><span>${esc(D.app.version)}</span></footer></main>${ui.overlayVisible&&D.live?overlayUI():''}${ui.toast?`<div class="toast" role="status">${ico('check')} ${esc(ui.toast)}</div>`:''}</div>`}

function license(withTip=false){const d=D.driver; const avatar=d.photo?`<img src="${d.photo}" alt="">`:ico('user');
  return `<div class="license" ${withTip?'data-nav="driver" role="button" tabindex="0" title="Otwórz pełną kartę kierowcy"':''}><div class="license-head"><div class="license-brand">${brandIcon(27)}<div><strong>BOXBOX ACADEMY</strong><small>LICENCJA KIEROWCY</small></div></div><strong class="license-level">L${d.level}</strong></div><div class="license-main"><div class="avatar">${avatar}</div><div><div class="license-name">${esc(d.nick||'KIEROWCA')}</div><div class="id">ID: ${esc(d.id)}</div><div style="margin-top:9px">${tagline(esc(D.app.gameShort)+' · Kierowca')}</div></div></div><div class="license-data"><div><small>Krok asyst</small><strong>${esc(d.stepText)}</strong></div><div><small>Tory</small><strong>${esc(d.tracksText)}</strong></div><div><small>Okrążenia</small><strong>${d.laps}</strong></div><div><small>Seria</small><strong>${esc(d.streakText)}</strong></div></div><div class="license-progress">${progress(d.progressPct)}</div><div class="license-foot"><span>${esc(d.nextText)}</span><span>od ${esc(d.since)}</span></div></div>`}

function ready(){const last=D.last, todo=D.todo;
  return `<div class="board"><div class="stack"><section class="panel hero"><svg class="hero-drawing" viewBox="0 0 300 300"><circle cx="150" cy="150" r="96"/><circle cx="150" cy="150" r="132"/><path d="M45 151 100 95q41-36 75 0l53 61-39 58q-54 28-108-3z"/></svg><div class="hero-top"><i class="dot" style="background:var(--red);box-shadow:0 0 11px var(--red)"></i> TWOJA NASTĘPNA SESJA</div><h2 class="hero-title">Każdy zakręt może być lepszy.</h2><p class="hero-description">${D.settings.autoStart?'Zostaw to okno, uruchom grę i wyjedź na tor: trener wystartuje sam, gdy gra wyśle telemetrię.':'Wyjedź na tor i naciśnij JEDŹ, a mechanik podpowie, jak pojechać pewniej.'}</p><div class="form-flex"><div><div class="label">TRYB JAZDY</div><div class="segmented"><button class="segment active">Nauka</button><button class="segment" disabled title="Tryb wyścigowy w przygotowaniu">Wyścig · wkrótce</button></div></div><div><label class="label" for="session-name">NAZWA SESJI</label><input id="session-name" class="field" value="${esc(ui.sessionName)}" placeholder="Np. Monza — hamowanie" maxlength="72"></div></div><div class="options-row">${quickSwitch('record','Nagrywaj sesję')}${quickSwitch('overlay','Nakładka na grze')}${quickSwitch('quiet','Tryb cicho')}</div><div class="hero-actions"><span class="action-hint">${ico('volume')} Głos mechanika: <strong style="color:#d5e0eb">${esc(D.settings.voice)}</strong> · ${D.status.connected?'gra połączona':'czekam na grę'}${D.settings.autoStart?' · start automatyczny':''}</span>${btn(`${ico('play')} JEDŹ`,'start-session','primary big')}</div></section><section class="panel">${head('Ostatnia sesja',last?`${esc(last.date)} · ${esc(last.track)}`:'Jeszcze żadnej sesji na tym komputerze',last?`<button class="link-btn" data-nav="analysis">Zobacz analizę →</button>`:'')}${last?`<div class="mini-metrics">${metric(esc(last.best),'Najlepsze okrążenie')}${metric(fmtDelta(last.delta),'Względem poprzednich sesji',deltaCls(last.delta))}${metric(last.laps,'Przejechane okrążenia')}</div>${last.toWork?`<div class="callout-amber mt-16"><div class="inline-icon" style="color:var(--amber);font-size:11px;font-weight:800">${ico('target')} JEDNA RZECZ DO POPRAWY</div><div class="small-txt mt-10">${esc(last.toWork)}</div></div>`:''}${last.good?`<div class="callout mt-16"><div class="inline-icon green" style="font-size:11px;font-weight:800">${ico('check')} DOBRZE</div><div class="small-txt mt-10">${esc(last.good)}</div></div>`:''}`:`<p class="small-txt">Po pierwszej sesji zobaczysz tu najlepszy czas, zmianę względem poprzednich dni i jedną rzecz do poprawy.</p>`}</section></div><div class="stack"><section class="panel" style="padding:14px">${license(true)}<div class="license-help" style="justify-content:center;margin:12px 0 0">${ico('arrow')} Kliknij plakietkę, aby otworzyć Kartę kierowcy</div></section><section class="panel">${head('Dziś do zrobienia','Najważniejsze zadanie na kolejny trening',tagline(`KROK ${todo.step} / 4`))}<div class="spaced"><div><div class="value">${todo.streak} <span class="muted" style="font-size:15px;font-weight:500">/ ${todo.needed}</span></div><div class="tiny mt-10">czyste okrążenia z rzędu${todo.track?` · ${esc(todo.track)}`:''}</div></div><span style="color:var(--green)">${ico('flag')}</span></div><div class="mt-16">${progress(100*todo.streak/todo.needed)}</div><div class="spaced mt-20"><div class="small-txt">Następnie: <strong style="color:#e7f1fd">${esc(todo.nextStep)}</strong></div>${btn('Zacznij lekcję →','open-lesson','ghost sm')}</div></section></div></div>`}
function quickSwitch(name,label){return `<div class="switch-row"><button aria-label="${label}" role="switch" aria-checked="${ui[name]}" class="switch ${ui[name]?'on':''}" data-toggle="${name}"></button><span class="switch-title">${label}</span></div>`}

// wykres: tablice 0..1 (własny i referencja) -> ścieżki SVG
function graph(key,own,ref,width=570,height=166,extra=null){ const n=(own&&own.length)||0;
  if(!n){return `<div class="chart-frame" style="display:flex;align-items:center;justify-content:center;color:#5d6b7c;font-size:12px;min-height:${height*0.6}px">Wykres pojawi się po pierwszym pełnym okrążeniu</div>`}
  const pts=[],rpts=[]; for(let i=0;i<n;i++){const x=(i/(n-1)*width).toFixed(1); pts.push(`${i?'L':'M'}${x} ${(14+(1-own[i])*(height-28)).toFixed(1)}`); if(ref&&ref.length===n) rpts.push(`${i?'L':'M'}${x} ${(14+(1-ref[i])*(height-28)).toFixed(1)}`)}
  const line=pts.join(' '),reference=rpts.join(' '),grid=[.2,.5,.8].map(y=>`<path d="M0 ${height*y}H${width}" class="chart-grid"/>`).join('');
  let extraPath=''; if(extra&&extra.length===n){ extraPath=`<path d="${extra.map((v,i)=>`${i?'L':'M'}${(i/(n-1)*width).toFixed(1)} ${(14+(1-v)*(height-28)).toFixed(1)}`).join(' ')}" fill="none" stroke="#ff3c42" stroke-width="1.8" opacity=".9"/>` }
  return `<svg class="chart-frame" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" role="img"><defs><linearGradient id="g-${key}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#19e6e6" stop-opacity=".16"/><stop offset="1" stop-color="#19e6e6" stop-opacity="0"/></linearGradient></defs>${grid}<path d="${line} L${width} ${height} L0 ${height}Z" fill="url(#g-${key})"/>${reference?`<path d="${reference}" class="chart-ref"/>`:''}${extraPath}<path d="${line}" class="chart-line"/></svg>`}

function live(){const L=D.live; const msgs=L.messages.slice(-3).reverse();
  return `<div class="live-banner"><div class="live-caption"><span class="live-pulse"></span><div><strong style="font-size:12px;letter-spacing:.08em">SESJA NA ŻYWO</strong><div style="font-size:11px;color:#a4aec0;margin-top:4px">${esc(L.name)} · ${sec(L.elapsed)} · ${L.recording?'Nagrywam':'Bez nagrywania'}${L.lesson?' · lekcja: '+esc(L.lesson):''}</div></div></div><div class="toolbar-group">${btn(ui.overlayVisible?'Ukryj podgląd nakładki':'Podgląd nakładki','toggle-overlay','ghost sm')}${btn(`${ico('stop')} Zakończ sesję`,'stop-session','ghost')}</div></div>${L.error?`<div class="callout-amber mb-18" style="border-color:var(--red)"><strong style="color:var(--red)">${esc(L.error)}</strong></div>`:''}<div class="board"><div class="stack"><section class="panel" style="min-height:480px"><div class="spaced"><span class="caps">${esc(L.lapLine||'CZEKAM NA TELEMETRIĘ')} ${L.lapLine?`<span style="margin:0 8px;color:#4c586a">/</span> ${L.pit?'PIT LANE':'TEMPO TRENINGOWE'}`:''}</span>${L.lapLine?tagline(L.invalid?'NIEWAŻNE':'WAŻNE'):''}</div><div class="mt-20"><span class="caps">NASTĘPNY ZAKRĘT</span><div class="live-huge">${esc(L.corner||'—')}</div><div class="inline-icon" style="color:var(--cyan);font-size:14px;font-weight:700">${L.corner?(L.dist==='TERAZ'?'teraz':'za '+esc(L.dist)):''} ${L.dist==='TERAZ'?'<span class="tag cyan">W ZAKRĘCIE</span>':L.corner?'<span class="tag cyan">ZBLIŻASZ SIĘ</span>':''}</div></div>${L.focus?`<div class="callout-amber mt-20"><strong style="font-size:10px;color:var(--amber);letter-spacing:.12em">NA TYM OKRĄŻENIU POPRAW</strong><div style="font-size:14px;font-weight:700;margin-top:7px">${esc(L.focus)}</div></div>`:''}<div class="divider"></div><div class="caps">OSTATNIE KOMUNIKATY MECHANIKA</div><div class="radio-log">${msgs.length?msgs.map(m=>`<div class="radio-entry"><span class="radio-time">${sec(m.t)}</span><p>${esc(m.text)}</p></div>`).join(''):'<div class="radio-entry"><span class="radio-time">--:--</span><p class="small-txt">Mechanik odezwie się po wyjeździe na tor.</p></div>'}</div>${L.goalText?`<div class="callout mt-16"><div class="spaced"><span class="small-txt" style="color:#dce6f1">${esc(L.goalText)}</span><strong class="green">${L.streak} / ${L.needed}</strong></div><div class="mt-10">${progress(100*L.streak/L.needed)}</div></div>`:''}</section></div><div class="stack"><section class="panel">${head('Prędkość','Ostatnie okrążenie vs najlepsze')}${graph('speed',L.chart.own,L.chart.ref)}<div class="chart-labels"><span>0 m</span><span>${esc(L.chart.mid)}</span><span>${esc(L.chart.end)}</span></div><div class="legend mt-16"><span><i></i> Ostatnie</span><span><i class="ref"></i> Najlepsze</span></div></section><div class="tiles">${metric(esc(L.best||'–'),'Najlepsze dziś')}${metric(fmtDelta(L.delta),'Do referencji',deltaCls(L.delta))}${metric(L.laps,'Okrążenia')}</div><section class="panel">${head('Stan sesji','Rejestrator i stan łącza')}<div class="info-row"><span>Próbkowanie</span><strong class="cyan-text">${L.rate} Hz</strong></div><div class="info-row"><span>Obciążenie</span><strong>${L.cpu}</strong></div><div class="info-row"><span>Plik nagrania</span><strong style="font:10px Consolas,monospace">${esc(L.recordingName||'bez nagrywania')}</strong></div><div class="small-txt mt-16">Sesja zakończy się sama, gdy gra przestanie wysyłać dane${D.settings.autoStopS?` (${D.settings.autoStopS} s)`:''}, albo przyciskiem powyżej.</div></section></div></div>`}

function summary(){const S=D.summary; if(!S) return ready();
  return `<div class="toolbar"><span class="tag green">${ico('check')} SESJA ZAKOŃCZONA</span><div class="toolbar-group">${btn('Nowa sesja','new-session','primary')}${btn('Zobacz analizę →','go-analysis','cyan')}</div></div><section class="panel mb-18"><div class="spaced"><div><div class="caps">${esc(S.track||'').toUpperCase()} · ${esc(S.name).toUpperCase()}</div><h2 style="font-size:28px;letter-spacing:-.05em;margin:8px 0">${S.laps} okrążeń <span style="color:#67798b">/</span> ${sec(S.elapsed)}</h2><p class="page-sub">${S.coach?'Trener ocenił każde pełne okrążenie względem referencji.':'Trener nie wystartował (brak pliku toru albo telemetrii); zapisano tylko przebieg.'}</p></div>${tagline(esc(S.date))}</div><div class="mini-metrics mt-20">${metric(esc(S.best||'–'),'Najlepsze okrążenie')}${metric(`${S.clean} / ${S.laps}`,'Czyste okrążenia')}${metric(fmtDelta(S.delta),'Zmiana vs poprzednie sesje',deltaCls(S.delta))}</div>${S.cpu?`<p class="small-txt mt-16">Obciążenie: ${esc(S.cpu)}</p>`:''}</section><div class="grid-2 mb-18"><section class="panel"><div class="inline-icon green" style="font-size:12px;font-weight:800">${ico('check')} DOBRZE</div><h2 class="section-title mt-16">${esc(S.good||'Sesja zapisana')}</h2></section><section class="panel"><div class="inline-icon amber" style="font-size:12px;font-weight:800">${ico('target')} DO PRACY</div><h2 class="section-title mt-16">${esc(S.toWork||'Nic pilnego')}</h2></section></div>${S.lesson?`<section class="panel mb-18"><div class="spaced"><div><div class="caps">LEKCJA</div><h2 class="section-title mt-10">${esc(S.lesson.title)}</h2></div><span class="tag ${S.lesson.passed?'green':'amber'}">${S.lesson.passed?'ZALICZONA':'JESZCZE NIE'} · seria ${S.lesson.best}/${S.lesson.needed}</span></div></section>`:''}<section class="panel mb-18">${head('Okrążenia','Każde pełne okrążenie z tej sesji')}<div class="table-wrap"><table class="data-table"><thead><tr><th>Numer</th><th>Czas</th><th>Δ do najlepszego</th><th>Ważne</th><th>Uwagi</th></tr></thead><tbody>${S.lapRows.map(r=>`<tr><td class="mono">${String(r.number).padStart(2,'0')}</td><td class="mono">${esc(r.time)}</td><td class="mono">${esc(r.delta)}</td><td>${r.valid?'<span class="tag green">Tak</span>':'<span class="tag red">Nie</span>'}</td><td>${r.notes}</td></tr>`).join('')}</tbody></table></div></section><section class="panel">${head('Zakręty najlepszego okrążenia','Pomiary z tej sesji względem referencji')}<div class="table-wrap"><table class="data-table"><thead><tr><th>Zakręt</th><th>v_min</th><th>Bieg</th><th>Hamowanie</th><th>Pełny gaz</th><th>Δ czasu</th></tr></thead><tbody>${S.cornerRows.map(r=>`<tr>${r.map(c=>`<td class="mono">${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="callout mt-20"><div class="spaced"><strong style="font-size:12px">Krok ${D.todo.step} · ${esc(D.todo.stepName)}</strong><span class="green" style="font-size:12px;font-weight:800">${D.todo.streak}/${D.todo.needed}</span></div><div class="mt-10">${progress(100*D.todo.streak/D.todo.needed)}</div><p class="small-txt">${esc(D.driver.nextText)}.</p></div><div class="toolbar-group mt-20">${btn('Zobacz analizę','go-analysis','cyan')}${btn('Drukuj raport (PDF)','print-pdf','ghost')}${btn('Nowa sesja','new-session','ghost')}</div></section>`}

function mapTrack(){const M=D.analysis.map; if(!M||!M.points.length){return `<div class="track-map" style="display:flex;align-items:center;justify-content:center;min-height:200px"><p class="small-txt" style="text-align:center;max-width:300px">Brak realnego kształtu tego toru. Nagraj jedno okrążenie recorderem (recorder.bat), a mapa pojawi się tutaj.</p></div>`}
  const d=M.points.map((p,i)=>`${i?'L':'M'}${p[0]} ${p[1]}`).join(' ')+'Z';
  return `<div class="track-map"><svg viewBox="0 0 500 270" role="img" aria-label="Kształt toru"><path class="track-baseline" d="${d}"/><path class="track-main" d="${d}"/><path class="track-dash" d="${d}"/>${M.corners.map(c=>`<g class="track-pin ${ui.corner===c.name?'active':''}" data-corner="${esc(c.name)}" role="button" tabindex="0"><circle cx="${c.x}" cy="${c.y}" r="9"/><text x="${c.x+13}" y="${c.y-13}">${esc(c.name)}</text></g>`).join('')}${M.start?`<circle cx="${M.start[0]}" cy="${M.start[1]}" r="5" fill="#35d07f" stroke="#0e1829" stroke-width="3"/>`:''}</svg></div>`}

function analysis(){const A=D.analysis; const sel=(id,opts,cur)=>`<select class="select" id="${id}">${opts.map(o=>`<option value="${esc(o.id)}" ${String(o.id)===String(cur)?'selected':''}>${esc(o.label)}</option>`).join('')}</select>`;
  if(!A.sessions.length) return `<section class="panel"><p class="small-txt">Analiza pojawi się po pierwszej sesji z pełnym okrążeniem.</p></section>`;
  const note=A.notes.find(n=>n.corner===ui.corner);
  return `<div class="toolbar"><div class="toolbar-group">${sel('an-session',A.sessions,A.session)}${sel('an-lap',A.laps,A.lap)}${sel('an-comp',A.comps,A.comp)}</div><span class="tag cyan">${ico('chart')} ${esc(A.lengthText)}</span></div><div class="board"><div class="stack"><section class="panel"><div class="spaced mb-18"><div><h2 class="section-title">Kanały telemetrii</h2><p class="section-sub">Linia cyjanowa — Ty · szara — ${esc(A.compLabel)}</p></div>${tagline(esc(A.lengthText))}</div><div class="chart-stack"><div><div class="spaced"><span class="caps">PRĘDKOŚĆ</span><span class="small-txt">km/h</span></div>${graph('speed',A.speed.own,A.speed.ref,570,126)}</div><div><div class="spaced"><span class="caps">GAZ (cyjan) I HAMULEC (czerwony)</span><span class="small-txt">%</span></div>${graph('pedal',A.pedal.own,A.pedal.ref,570,126,A.pedal.brake)}</div><div><div class="spaced"><span class="caps">DELTA CZASU</span><span class="small-txt">s · dodatnia = strata</span></div>${graph('delta',A.delta.own,null,570,96)}</div></div><div class="chart-labels">${A.axis.map(x=>`<span>${esc(x)}</span>`).join('')}</div><div class="legend mt-16"><span><i></i> Przejazd</span><span><i class="ref"></i> ${esc(A.compLabel)}</span></div></section></div><div class="stack"><section class="panel">${head('Mapa toru — '+esc(A.track),'Wybierz zakręt',`<span class="tag">${A.map&&A.map.corners?A.map.corners.length:0} zakrętów</span>`)}${mapTrack()}<div class="callout mt-16"><div class="spaced"><span class="caps">WYBRANY ZAKRĘT</span><strong class="cyan-text">${esc(ui.corner||'—')}</strong></div><p class="small-txt" style="margin-bottom:0">${note?esc(note.text):'Kliknij zakręt na mapie albo uwagę poniżej.'}</p></div></section><section class="panel">${head('Uwagi mechanika','Z tego okrążenia, względem referencji')}${A.notes.length?A.notes.map(r=>`<button class="note-item ${ui.corner===r.corner?'active':''}" data-corner="${esc(r.corner)}"><span class="note-num">${esc(r.corner)}</span><div style="flex:1;font-size:11px;line-height:1.5">${esc(r.text)}<small>${esc(r.delta)}</small></div></button>`).join(''):'<p class="small-txt">Brak uwag: czyste okrążenie.</p>'}<div class="toolbar-group mt-16">${btn('Eksport CSV','export-csv','ghost sm')}${btn('Drukuj PDF','print-pdf','ghost sm')}</div></section></div></div>`}

function progressScreen(){const P=D.progress; if(!P.tracks.length) return `<section class="panel"><p class="small-txt">Brak zapisanych okrążeń. Zrób pierwszą sesję z trenerem.</p></section>`;
  return `<div class="toolbar"><div class="pill-tabs">${P.tracks.map(t=>`<button class="pill ${P.active===t?'active':''}" data-track="${esc(t)}">${esc(t)}</button>`).join('')}</div><span class="tag cyan">${esc(D.app.gameShort)} · KROK ${P.step} / 4</span></div><div class="grid-2 mb-18"><section class="panel"><div class="spaced"><div><div class="caps">TWÓJ AKTUALNY POZIOM</div><div style="font-size:28px;font-weight:850;letter-spacing:-.05em;margin-top:9px">Krok ${P.step}: <span class="cyan-text">${esc(P.stepName)}</span></div></div><div style="font-size:48px;color:#19e6e6;font-weight:800">L${P.step}</div></div><div class="spaced mt-20"><span class="small-txt">Czyste okrążenia z rzędu</span><strong>${P.streak} / ${P.needed}</strong></div><div class="mt-10">${progress(100*P.streak/P.needed)}</div><p class="small-txt">${P.nextStep?`Następny krok: <strong style="color:#dce6f1">${esc(P.nextStep)}</strong>. ${esc(P.nextText)}`:'Jedziesz bez asyst: teraz pracujemy nad czasem.'}</p>${Object.keys(P.bestPerStep).length?`<div class="mt-16">${Object.entries(P.bestPerStep).map(([s,t])=>`<div class="info-row"><span>Najlepszy czas · krok ${s}</span><strong class="mono">${esc(t)}</strong></div>`).join('')}</div>`:''}</section><section class="panel">${head('Trend czasów',`Ostatnie ${P.trend.length} okrążeń · ${esc(P.active)}`,P.trendDelta!=null?tagline(fmtDelta(P.trendDelta)+' od pierwszego'):'')}${graph('trend',P.trend,null,570,148)}<div class="chart-labels"><span>${P.trend.length} okrążeń temu</span><span>Teraz</span></div></section></div><div class="grid-2 mb-18"><section class="panel">${head('Zakręty opanowane','Ostatnie 3 ważne okrążenia bez uwag')}<div class="pill-tabs">${P.mastered.length?P.mastered.map(c=>`<span class="tag green">${ico('check')} ${esc(c)}</span>`).join(''):'<span class="small-txt">jeszcze żaden</span>'}</div></section><section class="panel">${head('Do pracy','Nad tymi zakrętami pracuj w kolejnej sesji')}<div class="pill-tabs">${P.todo.length?P.todo.map(c=>`<span class="tag amber">${esc(c.corner)} · ${esc(c.rule)}</span>`).join(''):'<span class="small-txt">nic pilnego</span>'}</div></section></div><section class="panel mb-18">${head('Kamienie milowe','Odznaki przyznawane za konsekwentne treningi')}<div class="badges">${P.badges.map(r=>`<div class="achievement ${r.got?'':'locked'}" title="${esc(r.hint)}"><span class="badge-icon">${ico(r.icon)}</span><strong>${esc(r.name)}</strong></div>`).join('')}</div></section><section class="panel">${head('Historia przejazdów','Wszystkie pełne okrążenia na tym torze')}<div class="table-wrap"><table class="data-table"><thead><tr><th>Data</th><th>Okrążenie</th><th>Czas</th><th>Δ</th><th>Ważne</th><th>TC</th><th>ABS</th><th>Skrzynia</th><th>Uwagi</th></tr></thead><tbody>${P.history.map(r=>`<tr>${r.map((x,i)=>`<td ${i===2||i===3?'class="mono"':''}>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`}

function lessons(){const Ls=D.lessons; const cur=Ls.cards.find(c=>c.id===ui.lesson)||Ls.cards[0]; if(cur&&!ui.lesson) ui.lesson=cur.id;
  return `<div class="toolbar"><span class="caps">TWÓJ PROGRAM TRENINGOWY · FUNDAMENTY</span><span class="tag green">${Ls.cards.filter(c=>!c.premium).length} LEKCJE STARTOWE · DARMOWE</span></div><div class="lesson-grid">${Ls.cards.filter(c=>!c.premium).map(c=>`<section class="panel lesson-card"><div class="spaced"><div class="lesson-icon">${ico(c.icon)}</div><span class="tag ${c.status==='Zaliczona'?'green':c.status.includes('toku')?'cyan':''}">${esc(c.status)}</span></div><h3>${esc(c.title)}</h3><p>${esc(c.desc)}</p><div class="lesson-card-bottom"><span class="tiny">${ico('clock')} ${c.laps} okrążeń</span><button class="link-btn" data-lesson="${esc(c.id)}">${c.status==='Zaliczona'?'Powtórz':'Szczegóły'} →</button></div></section>`).join('')}</div>${cur?`<div class="panel mt-20"><div class="lesson-detail"><div><div class="caps">WYBRANA LEKCJA</div><h2 style="font-size:26px;letter-spacing:-.045em;margin:10px 0">${esc(cur.title)}</h2><p class="small-txt">${esc(cur.goal)}</p>${cur.explain?`<p class="small-txt">${esc(cur.explain)}</p>`:''}<div class="callout mt-16"><strong style="font-size:12px">Cel mierzalny</strong><p class="small-txt" style="margin:7px 0 0">${esc(cur.passText)} Trener skupia się wyłącznie na wybranej umiejętności.</p></div>${cur.cornerOnly?`<div class="mt-16"><label class="label" for="lesson-corner">ZAKRĘT DO ĆWICZENIA (numer z gry, np. 1)</label><input id="lesson-corner" class="field" style="max-width:160px" value="${esc(ui.lessonCorner||'')}" placeholder="np. 1"></div>`:''}<div class="mt-20">${btn(`${ico('play')} Zacznij lekcję`,'start-lesson','primary')}</div></div><div class="exercise-road"><svg viewBox="0 0 350 170" aria-label="Schemat zakrętu"><path d="M16 120H105Q135 120 144 98L164 57Q176 23 216 24H337" fill="none" stroke="#536275" stroke-width="28" stroke-linecap="round"/><path d="M16 120H105Q135 120 144 98L164 57Q176 23 216 24H337" fill="none" stroke="#9faebe" stroke-width="3" stroke-dasharray="7 8"/><circle cx="99" cy="120" r="8" fill="#ff3c42"/><path d="M99 106V59" stroke="#ff3c42" stroke-width="1.5" stroke-dasharray="3 5"/><text x="68" y="47" font-size="10" fill="#ff777b">HAMOWANIE</text><circle cx="197" cy="30" r="6" fill="#19e6e6"/><text x="214" y="63" font-size="10" fill="#19e6e6">APEKS</text></svg></div></div></div>`:''}<section class="panel mt-20"><div class="spaced"><div><h2 class="section-title">Rozbudowany plan nauki</h2><p class="section-sub">${Ls.cards.filter(c=>c.premium).map(c=>esc(c.title)).join(' · ')} i tryb „wytłumacz mi”.</p></div><span class="tag planned">PIT CREW · PO BECIE</span></div></section>`}

function driver(){const d=D.driver;
  return `<div class="grid-2"><div class="stack"><section class="panel"><div class="spaced mb-18"><div><h2 class="section-title">Licencja kierowcy</h2><p class="section-sub">Zdobywasz poziom wraz z kolejnymi krokami asyst.</p></div>${tagline('POZIOM L'+d.level)}</div><div class="full-license">${license()}</div><div class="toolbar-group mt-20">${btn(`${ico('download')} Zapisz plakietkę jako PNG`,'export-license','cyan')}${btn('Jak działa licencja?','license-help','ghost')}</div></section><section class="panel">${head('Informacje kierowcy')}<div class="setting-block"><label class="label" for="driver-nick">NICK</label><div class="form-flex"><input id="driver-nick" class="field" value="${esc(d.nick)}" maxlength="24">${btn('Zapisz','save-nick','cyan sm')}</div></div><div class="info-row"><span>Identyfikator</span><strong>${esc(d.id)}</strong></div><div class="info-row"><span>Dołączył</span><strong>${esc(d.since)}</strong></div><div class="setting-block"><div class="setting-head"><div><strong>Zdjęcie</strong><small>Wybierz z Obrazów lub Pulpitu, albo przeciągnij plik na to okno.</small></div>${btn(ui.photoPicker?'Zamknij':'Wybierz zdjęcie','pick-photo','ghost sm')}</div>${ui.photoPicker?`<div class="photo-grid">${ui.photos.length?ui.photos.map(p=>`<button data-photo="${esc(p.path)}" title="${esc(p.name)}"><img src="${p.thumb}" alt=""></button>`).join(''):'<p class="small-txt">Brak obrazów w folderach Obrazy i Pulpit. Przeciągnij plik na okno.</p>'}</div>`:''}</div><div class="setting-block">${switcher('consent','Anonimowe statystyki do przyszłego rankingu','Domyślnie wyłączone. W becie nic nie jest wysyłane.')}</div></section></div><div class="stack"><div class="grid-2">${metric(d.sessions,'Sesje')}${metric(d.laps,'Okrążenia')}${metric(d.tracks.length,'Tory')}${metric(esc(d.hours),'Godzin na torze')}</div><section class="panel">${head('Twoje tory','Najlepsze czasy i aktualne kroki asyst')}${d.tracks.length?d.tracks.map(t=>`<div class="info-row"><span><strong style="color:#e3e9f0">${esc(t.name)}</strong><div class="small-txt">${t.mastered} / ${t.corners} zakrętów · ${t.laps} okr.</div></span><strong>${esc(t.best)}<br><small style="color:${t.step>1?'var(--cyan)':'#96a5b7'}">Krok ${t.step}</small></strong></div>`).join(''):'<p class="small-txt">Jeszcze żadnego toru.</p>'}</section><section class="panel"><div class="inline-icon">${[1,2,3,4].map(l=>`<span class="tag ${l<d.level?'green':l===d.level?'cyan':''}">L${l}</span>${l<4?`<div class="progress" style="flex:1">${progress(l<d.level?100:l===d.level?d.progressPct:0)}</div>`:''}`).join('')}</div><p class="small-txt mt-16">L1 — automat i pełne asysty · L2 — TC średnia · L3 — bez TC · L4 — bez TC i ABS.</p></section></div></div>`}

function settings(){let tabs=[['sound','Dźwięk'],['overlay','Nakładka'],['game','Gra'],['data','Dane'],['help','Pomoc']];return `<div class="settings-grid"><div class="panel" style="align-self:start;padding:13px"><nav class="settings-side">${tabs.map(t=>`<button class="${ui.settingsTab===t[0]?'active':''}" data-settings="${t[0]}">${t[1]}</button>`).join('')}</nav></div><section class="panel" style="min-height:425px">${settingsBody()}</section></div>`}
function settingsBody(){const s=D.settings; switch(ui.settingsTab){
 case 'sound':return `${head('Dźwięk i mechanik','Ustaw sposób, w jaki trener komunikuje się z kierowcą')}<div class="setting-block"><div class="setting-head"><div><strong>Głośność komunikatów</strong><small>Ponad 100% to wzmocnienie na tle głośnej gry.</small></div><strong class="cyan-text">${s.volume}%</strong></div><input type="range" class="slider" id="volume" min="30" max="300" step="10" value="${s.volume}"><div>${btn(`${ico('volume')} Odtwórz próbkę`,'audio-sample','ghost sm')}</div></div><div class="setting-block">${switcher('quietDefault','Tryb cicho domyślnie','Mechanik odzywa się tylko po zakończeniu okrążenia.')}</div><div class="setting-block">${switcher('explain','Tryb „wytłumacz mi”','Przy pierwszej uwadze danego typu trener mówi dłuższą wersję z wyjaśnieniem.')}</div><div class="setting-block"><label class="label">GŁOS MECHANIKA</label><select class="select" disabled><option>${esc(s.voice)} · neutralny i dojrzały</option></select><p class="small-txt">Inne głosy: Pit Crew, po becie.</p></div>`;
 case 'overlay':return `${head('Nakładka na grze','Osobne okno nad grą: zakręt, uwagi mechanika, cel')}<div class="setting-block">${switcher('overlayDefault','Pokazuj nakładkę w grze','Gra musi działać w trybie okna bez ramki.')}</div><div class="setting-block"><div class="setting-head"><strong>Skala nakładki</strong><strong class="cyan-text">${s.scale}%</strong></div><input type="range" class="slider" min="65" max="160" step="5" id="scale" value="${s.scale}"></div><div class="setting-block"><div class="setting-head"><strong>Krycie tła</strong><strong class="cyan-text">${s.opacity}%</strong></div><input type="range" class="slider" id="opacity" min="40" max="100" value="${s.opacity}"></div><div class="setting-block">${btn('Pokaż nakładkę na 5 s','preview-overlay','cyan')}</div>`;
 case 'game':return `${head('Gra i telemetria',`Połączenie UDP: ${esc(D.app.game)}`)}<div class="setting-block"><label class="label">GRA</label><select class="select" disabled><option>${esc(D.app.gameShort)} · jedyna obsługiwana gra w becie</option></select><p class="small-txt">Wybór gry odblokuje się po dodaniu kolejnych adapterów.</p></div><div class="info-row"><span>Format pakietów</span><strong>${esc(D.status.fmt||'2025 / 2026')}</strong></div><div class="info-row"><span>Port UDP</span><strong><input id="port" class="field" style="width:110px;padding:6px 10px" value="${s.port}"></strong></div><div class="info-row"><span>Adres IP w grze</span><strong>127.0.0.1</strong></div><div class="setting-block">${switcher('autoStart','Start automatyczny','Trener rusza sam, gdy gra zacznie wysyłać telemetrię; sesja kończy się sama bez sygnału.')}</div><div class="mt-20">${btn('Sprawdź telemetrię (nasłuch 5 s)','check-telemetry','cyan')} <span class="small-txt" id="check-result">${esc(D.wizard.checkResult||'')}</span></div>`;
 case 'data':return `${head('Nagrania i dane','Prywatne pliki na Twoim komputerze')}<div class="setting-block"><div class="setting-head"><div><strong>Folder danych</strong><small>${esc(D.app.dataDir)}</small></div>${btn('Otwórz folder','open-data','ghost sm')}</div></div><div class="setting-block">${switcher('record','Domyślnie nagrywaj sesje','Pozwala wrócić do przebiegów i zgłosić błąd z nagraniem.')}</div><div class="setting-block"><div class="info-row"><span>Sesje w bazie</span><strong>${D.driver.sessions}</strong></div><div class="info-row"><span>Okrążenia w bazie</span><strong>${D.driver.laps}</strong></div></div><div class="setting-block">${btn('Zapakuj raport błędu','report-bug','ghost')}<p class="small-txt">Pakuje dziennik, bazę, ustawienia i ostatnie nagranie do ZIP.</p></div>`;
 case 'help':return `${head('Pomoc i aktualizacje','Najważniejsze zasoby dla początkującego')}<div class="setting-block">${btn('Uruchom kreator jeszcze raz','open-wizard','cyan')} ${btn('Otwórz samouczek','tutorial','ghost')}</div><div class="setting-block">${btn('Słownik pojęć','glossary','ghost')} ${btn('Zgłoś błąd','report-bug','ghost')}</div><div class="info-row"><span>Wersja</span><strong>${esc(D.app.version)} · ${esc(D.app.build)}</strong></div><div class="info-row"><span>Aktualizacje automatyczne</span><span class="tag planned">PO BECIE</span></div>`;}}

function wizard(){const titles=['Telemetria','Głośniki','Asysty','Kierowca'];let s=ui.wizardStep;const W=D.wizard;
  return `<div class="wizard-shell"><div class="steps">${titles.map((title,i)=>`<div class="step ${i===s?'active':i<s?'done':''}"><b>${i<s?'✓':String(i+1).padStart(2,'0')}</b>${title}</div>`).join('')}</div><section class="panel" style="padding:33px;min-height:400px"><div class="caps">KROK ${s+1} / 4</div><h2 style="font-size:29px;letter-spacing:-.05em;margin:12px 0">${['Połącz telemetrię z grą','Sprawdź dźwięk mechanika','Ustaw asysty na początek','Stwórz kartę kierowcy'][s]}</h2><p class="small-txt mb-18">${['Sprawdź, czy gra wysyła dane do BoxBox Academy.','Komunikaty trenera powinny być wyraźne, ale nie za głośne.','To zalecany zestaw dla pierwszych treningów.','Wybierz nazwę wyświetlaną na Twojej licencji.'][s]}</p>${s===0?`<div class="info-grid">${[['Telemetria UDP','Włączona'],['Tryb rozgłaszania','Wyłączony'],['Adres IP','127.0.0.1'],['Port',String(D.settings.port)],['Częstotliwość','60 Hz'],['Format','2025 lub 2026'],['Twoja telemetria','Publiczna']].map(([k,v])=>`<div class="info-row"><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><div class="mt-20">${btn(W.checking?'Nasłuchuję...':'Sprawdź (nasłuch 5 s)','check-telemetry','cyan',W.checking?'disabled':'')}<p class="small-txt" id="check-result">${esc(W.checkResult||'W grze: Ustawienia → Telemetria. Potem wróć tu i naciśnij Sprawdź.')}</p></div>`:s===1?`<div class="callout"><div class="inline-icon">${ico('headphones')} <strong>Test głośników</strong></div><p class="small-txt">Kliknij „Odtwórz powitanie”, następnie wybierz wynik testu.</p><div class="toolbar-group mt-16">${btn('Odtwórz powitanie','audio-sample','cyan')}${btn('Słyszę','hear-yes','ghost')}${btn('Nie słyszę','hear-no','ghost')}</div><p class="small-txt mt-10">${esc(W.hearResult||'')}</p></div>`:s===2?`<div class="info-grid">${[['Skrzynia biegów','Automatyczna'],['Kontrola trakcji (TC)','Pełna'],['ABS','Włączony'],['Linia jazdy','Pełna'],['Asysta ERS','Wyłączona'],['Flashback','Nie używaj']].map(([k,v])=>`<div class="info-row"><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><div class="callout mt-20"><strong>Trener powie, kiedy co zdjąć.</strong> Po trzech czystych okrążeniach z rzędu zaproponuje kolejny krok.</div>`:`<div class="form-flex"><div><label class="label" for="driver-nick">NICK KIEROWCY</label><input id="driver-nick" class="field" value="${esc(D.driver.nick)}" maxlength="24" placeholder="np. Driver77"></div><div><span class="label">ZDJĘCIE</span><p class="small-txt">Dodasz je w Karcie kierowcy.</p></div></div><div class="setting-block mt-16">${switcher('consent','Anonimowe statystyki do przyszłego rankingu','Opcjonalne, domyślnie wyłączone. W becie nic nie jest wysyłane.')}</div>`}<div class="spaced mt-20"><div>${btn('Wstecz','wizard-back','ghost')}</div>${btn(s===3?'Zakończ i przejdź do Startu':'Dalej →','wizard-next','primary')}</div></section></div>`}

function help(){const terms=D.glossary;
  return `<div class="pill-tabs mb-18">${[['glossary','Słownik'],['tutorial','Samouczek'],['report','Raport błędu']].map(t=>`<button class="pill ${ui.helpTab===t[0]?'active':''}" data-help="${t[0]}">${t[1]}</button>`).join('')}</div>${ui.helpTab==='glossary'?`<div class="grid-2">${terms.map(([name,desc])=>`<section class="panel"><div class="inline-icon cyan-text">${ico('book')} <strong style="font-size:14px">${esc(name)}</strong></div><p class="small-txt" style="margin:15px 0 0">${esc(desc)}</p></section>`).join('')}</div>`:ui.helpTab==='tutorial'?`<section class="panel">${head('Jak wygląda pierwszy trening?','Trzy kroki od uruchomienia do poprawiania czasu')}<div class="info-row"><span>01 · Ustaw telemetrię UDP w grze</span><strong>Port ${D.settings.port}, 127.0.0.1</strong></div><div class="info-row"><span>02 · Zostaw to okno i uruchom grę</span><strong>Trener startuje sam</strong></div><div class="info-row"><span>03 · Wyjedź na tor w Time Trial albo treningu</span><strong>Po pierwszym pełnym okrążeniu uwagi po zakrętach</strong></div><div class="info-row"><span>04 · Po sesji</span><strong>Podsumowanie, Analiza, Postęp</strong></div><div class="mt-20">${btn('Przejdź do kreatora','open-wizard','primary')}</div></section>`:`<section class="panel" style="max-width:760px">${head('Zgłoszenie błędu','Opisz problem. Program spakuje dziennik, bazę i ostatnie nagranie do ZIP.')}<label for="bug-desc" class="label">CO SIĘ STAŁO?</label><textarea id="bug-desc" class="textarea" placeholder="Np. Trener nie odtwarza komunikatów na Monzy...">${esc(ui.bugDesc||'')}</textarea><div class="mt-16">${btn('Zapakuj raport','report-bug-now','cyan')}</div><p class="small-txt">${esc(D.wizard.bugResult||'Plik ZIP trafi do folderu raporty-bledow; wyślij go tak jak nagrania.')}</p></section>`}`}

function overlayUI(){const L=D.live; const msgs=L.messages.slice(-3).reverse();
  return `<aside class="overlay" aria-label="Podgląd nakładki"><div class="overlay-bar"><strong>BOXBOX ACADEMY / NAKŁADKA (PODGLĄD)</strong><span style="color:var(--red);font-weight:800">● LIVE</span></div><div class="spaced mt-16"><div><span class="caps">${esc(L.lapLine||'')}</span><div class="overlay-corner">${esc(L.corner||'—')} <span style="font-size:14px;font-weight:600;color:#d6e6f0">${L.dist==='TERAZ'?'teraz':L.dist?'za '+esc(L.dist):''}</span></div></div><span class="tag cyan">NAUKA</span></div>${L.focus?`<div class="overlay-line" style="color:var(--amber)">${esc(L.focus)}</div>`:''}${msgs.map(m=>`<div class="overlay-line"><span class="radio-time">${sec(m.t)}</span> ${esc(m.text)}</div>`).join('')}${L.goalText?`<div class="overlay-goal mt-16"><div class="spaced"><span style="font-size:11px">${esc(L.goalText)}</span><strong class="green">${L.streak}/${L.needed}</strong></div><div class="mt-10">${progress(100*L.streak/L.needed)}</div></div>`:''}<div class="spaced mt-16" style="font:10px Consolas,monospace;color:#8ba0b5"><span>${esc(L.statusLine||'')}</span><span style="color:var(--green)">${L.recording?'● NAGRYWANIE':''}</span></div></aside>`}

function renderView(){switch(ui.view){case 'start':return D.live?live():ready();case 'analysis':return analysis();case 'progress':return progressScreen();case 'lessons':return lessons();case 'driver':return driver();case 'settings':return settings();case 'wizard':return wizard();case 'summary':return summary();case 'help':return help();default:return ready()}}
const app=document.getElementById('app');let toastTimer=null;
function render(){ if(!D) return; const active=document.activeElement; const keep=active&&active.id&&['session-name','driver-nick','bug-desc','lesson-corner','port'].includes(active.id)?{id:active.id,pos:active.selectionStart}:null;
  app.innerHTML=shell(); document.title=`BoxBox Academy | ${H[ui.view]?.[0]||'Start'}`;
  if(keep){const el=document.getElementById(keep.id); if(el){el.focus(); try{el.setSelectionRange(keep.pos,keep.pos)}catch(e){}}} }
function navigate(next){ui.view=next;ui.overlayVisible=false;ui.photoPicker=false;render();window.scrollTo({top:0,behavior:'instant'});}
function toast(msg){ui.toast=msg;render();clearTimeout(toastTimer);toastTimer=setTimeout(()=>{ui.toast='';render()},3800)}
const call=(name,...args)=>{ if(bridge&&bridge[name]) return bridge[name](...args); };

function action(a){switch(a){
 case 'start-session': call('startSession', JSON.stringify({name:ui.sessionName,record:ui.record,overlay:ui.overlay,quiet:ui.quiet,lesson:'',corner:0})); break;
 case 'stop-session': call('stopSession'); break;
 case 'new-session': D.summary=null; navigate('start'); break;
 case 'go-analysis': navigate('analysis'); break;
 case 'open-lesson': navigate('lessons'); break;
 case 'start-lesson': { const corner=parseInt((document.getElementById('lesson-corner')||{}).value||'0')||0; ui.lessonCorner=corner||''; call('startSession', JSON.stringify({name:'Lekcja',record:ui.record,overlay:ui.overlay,quiet:false,lesson:ui.lesson,corner})); navigate('start'); break; }
 case 'toggle-overlay': ui.overlayVisible=!ui.overlayVisible; render(); break;
 case 'preview-overlay': call('previewOverlay'); toast('Nakładka pokazana na 5 s'); break;
 case 'wizard-next': if(ui.wizardStep<3){ui.wizardStep++;render()} else { const nick=(document.getElementById('driver-nick')||{}).value||''; call('finishWizard', nick); navigate('start'); } break;
 case 'wizard-back': if(ui.wizardStep>0){ui.wizardStep--;render()} else navigate('start'); break;
 case 'open-wizard': ui.wizardStep=0; navigate('wizard'); break;
 case 'tutorial': ui.helpTab='tutorial'; navigate('help'); break;
 case 'glossary': ui.helpTab='glossary'; navigate('help'); break;
 case 'report-bug': ui.helpTab='report'; navigate('help'); break;
 case 'report-bug-now': { ui.bugDesc=(document.getElementById('bug-desc')||{}).value||''; call('bugReport', ui.bugDesc); break; }
 case 'check-telemetry': call('checkTelemetry'); break;
 case 'audio-sample': call('playSample'); toast('Odtwarzam powitanie'); break;
 case 'hear-yes': D.wizard.hearResult='Dobrze. Głośność zmienisz w Ustawieniach → Dźwięk.'; render(); break;
 case 'hear-no': D.wizard.hearResult='Sprawdź w Windows: Ustawienia → Dźwięk → urządzenie wyjściowe (słuchawki/głośniki) i głośność, potem Odtwórz ponownie.'; render(); break;
 case 'license-help': toast('Poziom licencji to najwyższy osiągnięty krok asyst na dowolnym torze.'); break;
 case 'export-csv': call('exportCsv'); break;
 case 'print-pdf': call('printPdf'); break;
 case 'export-license': exportLicense(); break;
 case 'save-nick': { const nick=(document.getElementById('driver-nick')||{}).value||''; call('setSetting', JSON.stringify({nick})); toast('Zapisano nick'); break; }
 case 'pick-photo': ui.photoPicker=!ui.photoPicker; if(ui.photoPicker) call('listPhotos'); render(); break;
 case 'open-data': call('openDataDir'); break;
 default: break; } }

function exportLicense(){const d=D.driver;let c=document.createElement('canvas');c.width=980;c.height=565;const g=c.getContext('2d');const grd=g.createLinearGradient(0,0,980,565);grd.addColorStop(0,'#253044');grd.addColorStop(1,'#0c131f');g.fillStyle=grd;g.fillRect(0,0,980,565);g.fillStyle='#ff3c42';g.fillRect(0,136,980,7);g.fillStyle='#f1f5fa';g.font='bold 40px Segoe UI, Arial';g.fillText('BOXBOX ACADEMY',54,77);g.fillStyle='#9aacc1';g.font='19px Segoe UI, Arial';g.fillText('LICENCJA KIEROWCY',56,113);g.fillStyle='#19e6e6';g.font='bold 58px Segoe UI, Arial';g.fillText('L'+d.level,835,105);g.fillStyle='#f1f5fa';g.font='bold 62px Segoe UI, Arial';g.fillText((d.nick||'KIEROWCA').toUpperCase(),66,248);g.fillStyle='#19e6e6';g.font='25px Segoe UI, Arial';g.fillText(d.id,66,286);g.fillStyle='#b2c2d2';g.font='27px Segoe UI, Arial';g.fillText('Krok asyst  ·  '+d.stepText,65,358);g.fillText('Tory  ·  '+d.tracksText,65,402);g.fillText('Okrążenia  ·  '+d.laps,65,446);g.fillText('Seria  ·  '+d.streakText,65,490);g.fillStyle='#314255';g.fillRect(580,457,334,15);g.fillStyle='#35d07f';g.fillRect(580,457,Math.round(334*d.progressPct/100),15);g.fillStyle='#718499';g.font='18px Segoe UI, Arial';g.fillText('BOXBOX ACADEMY · od '+d.since,580,510);call('saveLicensePng', c.toDataURL('image/png'));}

app.addEventListener('click',e=>{const n=e.target.closest('[data-nav]');if(n){navigate(n.dataset.nav);return}const a=e.target.closest('[data-action]');if(a){action(a.dataset.action);return}const t=e.target.closest('[data-toggle]');if(t){const x=t.dataset.toggle; if(['record','overlay','quiet'].includes(x)){ui[x]=!ui[x]} else {D.settings[x]=!D.settings[x]; call('setSetting', JSON.stringify({[x]:D.settings[x]}))} render();return}const cor=e.target.closest('[data-corner]');if(cor){ui.corner=cor.dataset.corner;render();return}const tr=e.target.closest('[data-track]');if(tr){call('selectTrack',tr.dataset.track);return}const st=e.target.closest('[data-settings]');if(st){ui.settingsTab=st.dataset.settings;render();return}const help=e.target.closest('[data-help]');if(help){ui.helpTab=help.dataset.help;render();return}const les=e.target.closest('[data-lesson]');if(les){ui.lesson=les.dataset.lesson;render();return}const ph=e.target.closest('[data-photo]');if(ph){call('setPhoto',ph.dataset.photo);ui.photoPicker=false;return}});
app.addEventListener('change',e=>{const id=e.target.id; if(id==='session-name'){ui.sessionName=e.target.value} if(id==='an-session'){call('selectAnalysis',JSON.stringify({session:e.target.value}))} if(id==='an-lap'){call('selectAnalysis',JSON.stringify({lap:e.target.value}))} if(id==='an-comp'){call('selectAnalysis',JSON.stringify({comp:e.target.value}))} if(id==='volume'){call('setSetting',JSON.stringify({volume:parseInt(e.target.value)}))} if(id==='scale'){call('setSetting',JSON.stringify({scale:parseInt(e.target.value)}))} if(id==='opacity'){call('setSetting',JSON.stringify({opacity:parseInt(e.target.value)}))} if(id==='port'){call('setSetting',JSON.stringify({port:parseInt(e.target.value)||20777}))} if(id==='lesson-corner'){ui.lessonCorner=e.target.value}});
app.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.license[data-nav]')){e.preventDefault();navigate('driver')}});
document.addEventListener('dragover',e=>e.preventDefault()); document.addEventListener('drop',e=>{e.preventDefault(); const f=e.dataTransfer.files&&e.dataTransfer.files[0]; if(f&&f.path) call('setPhoto', f.path);});

// --- połączenie z Pythonem ---
function applyData(json, partial){ const d=typeof json==='string'?JSON.parse(json):json; if(partial&&D){ Object.assign(D,d) } else { D=d } ; if(D && d.view){ ui.view=d.view } render(); }
window.boxbox = { applyData, toast, navigate, ui };
function connect(){ if(typeof QWebChannel==='undefined'||!window.qt||!qt.webChannelTransport){ return false }
  new QWebChannel(qt.webChannelTransport, ch => { bridge = ch.objects.bridge; window.boxbox.bridge = bridge; bridge.dataChanged.connect(j=>applyData(j,false)); bridge.liveChanged.connect(j=>applyData(j,true)); bridge.toast.connect(m=>toast(m)); bridge.navigateTo.connect(v=>navigate(v)); bridge.photos.connect(j=>{ui.photos=JSON.parse(j);render()}); bridge.getData(j=>{ applyData(j,false); if(!D.settings.wizardDone){ ui.wizardStep=0; navigate('wizard') } ui.sessionName=D.defaultSessionName||'sesja'; ui.record=!!D.settings.record; ui.overlay=!!D.settings.overlayDefault; ui.quiet=!!D.settings.quietDefault; render(); }); });
  return true; }
if(!connect()){ // podgląd w przeglądarce bez Pythona: dane przykładowe z pliku demo.js (jeśli jest)
  const s=document.createElement('script'); s.src='demo.js'; s.onload=()=>{ if(window.DEMO) applyData(window.DEMO,false) }; document.body.appendChild(s); }
})();
